INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Werden Trigger immer bei jeder Datenänderung ausgeführt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei definierten Ereignissen"}, {"text": "Ja", "correct": false, "because": "Ereignisabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von Triggern?', 3, '[{"text": "Automatisierung", "correct": true, "because": "Reagiert auf Ereignisse"}, {"text": "Schnelle Einrichtung", "correct": false, "because": "Logik wichtiger"}, {"text": "Minimale Größe", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ereignisse können Trigger auslösen?', 5, '[{"text": "INSERT", "correct": true, "because": "Daten hinzufügen"}, {"text": "UPDATE", "correct": true, "because": "Daten ändern"}, {"text": "SELECT", "correct": false, "because": "Nur Abfrage"}, {"text": "INSTALL", "correct": false, "because": "Kein Datenereignis"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Trigger sichern Datenintegrität. b) Sie ersetzen Stored Procedures.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschiedene Zwecke"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit Triggern?', 4, '[{"text": "Ereignisdefinition", "correct": false, "because": "Kern der Trigger"}, {"text": "Logik", "correct": false, "because": "Definiert Aktion"}, {"text": "Farbanpassung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Trigger auch vor einem Ereignis ausgeführt werden können?', 2, '[{"text": "Ja", "correct": true, "because": "BEFORE-Trigger möglich"}, {"text": "Nein", "correct": false, "because": "Vor und nach möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Trigger wähle ich, um Daten vor dem Löschen zu sichern?', 3, '[{"text": "BEFORE DELETE", "correct": true, "because": "Greift vor dem Ereignis"}, {"text": "AFTER INSERT", "correct": false, "because": "Falsches Ereignis"}, {"text": "ON SELECT", "correct": false, "because": "Kein Trigger-Ereignis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen mir Trigger?', 5, '[{"text": "Automatische Reaktion", "correct": true, "because": "Ereignisgesteuert"}, {"text": "Integritätssicherung", "correct": true, "because": "Regeln durchsetzen"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Trigger reagieren auf Änderungen. b) Sie sind immer performant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Performance variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Trigger?', 4, '[{"text": "Ereignis", "correct": false, "because": "Definiert Auslösung"}, {"text": "Aktion", "correct": false, "because": "Definiert Reaktion"}, {"text": "Spielmodus", "correct": true, "because": "Kein Datenbankzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Trigger nur für große Datenbanken sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Nützlich unabhängig von Größe"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Trigger effektiv?', 4, '[{"text": "Klare Ereignisse", "correct": true, "because": "Sichern Auslösung"}, {"text": "Präzise Logik", "correct": true, "because": "Definiert Verhalten"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Trigger die Performance immer verbessern. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können Last erhöhen"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Trigger-Definition?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Schützt Konsistenz"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Funktion wichtiger"}, {"text": "Minimale Zeilen", "correct": false, "because": "Logik zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Trigger können Änderungen prüfen. b) Sie ersetzen manuelle Checks komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Manuelle Checks ergänzend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen verbessern Trigger?', 5, '[{"text": "Fehlerbehandlung", "correct": true, "because": "Sichert Robustheit"}, {"text": "Protokollierung", "correct": true, "because": "Nachverfolgbarkeit"}, {"text": "Manuelle Auslösung", "correct": false, "because": "Nicht automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Triggern unwichtig?', 3, '[{"text": "Ereignisbindung", "correct": false, "because": "Kern der Trigger"}, {"text": "Logikdefinition", "correct": false, "because": "Definiert Aktion"}, {"text": "GUI-Design", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können Trigger rekursiv sein?', 3, '[{"text": "Ja", "correct": true, "because": "Selbstaufruf möglich"}, {"text": "Nein", "correct": false, "because": "Konfigurierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Trigger auch für Audits geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Änderungen protokollieren"}, {"text": "Nein", "correct": false, "because": "Häufige Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel passt zu Triggern?', 4, '[{"text": "Automatisches Logging", "correct": true, "because": "Reagiert auf Änderungen"}, {"text": "Manuelle Abfragen", "correct": false, "because": "Nicht automatisch"}, {"text": "Tabellenkopien", "correct": false, "because": "Keine Logik"}]');
